import {esc,macroParams} from '../editor/model.js';
import {icon} from '../../shared/icons.js';
import {renderPreview} from '../editor/preview.js';
import {renderMolecule} from '../editor/molecule-preview.js';
import {createMolecule,moleculeFormula} from '../editor/molecule.js';
import {openMoleculeEditor} from '../editor/molecule-editor.js';
import {materialRoute,createPhysicalModel,savePhysicalModel,touchModel,updateMaterial,checkPhysicalModel} from './model.js';

const action=(key,label,glyph='',extra='')=>`<button type="button" class="btn" data-physical="${key}" ${extra}>${glyph?icon(glyph):''}${label}</button>`;
const input=(name,label,value,unit='',type='number')=>`<label class="physical-field"><span>${label}${unit?` <small>${unit}</small>`:''}</span><input name="${name}" aria-label="${label}" type="${type}" step="any" value="${esc(value??'')}"></label>`;
const select=(name,label,value,items)=>`<label class="physical-field"><span>${label}</span><select name="${name}" aria-label="${label}">${items.map(item=>`<option ${item===value?'selected':''}>${esc(item)}</option>`).join('')}</select></label>`;
const sections=[['geometry','几何','grid'],['materials','材料','molecule'],['physics','物理场','flask'],['boundary','边界条件','flow'],['mesh','网格','grid']];

export function renderPhysicalEditor(s,materialId){
  const m=s.materials.find(m=>m.id===materialId);
  return `<div class="physical-editor" data-ui><header class="physical-header"><div class="physical-heading">${materialId?action('back-model','返回物理模型','chevron'):'<button class="editor-back" data-action="back" aria-label="返回工作流列表">'+icon('chevron')+'</button>'}<div>${materialId?`<span class="physical-context">${esc(s.name)} / 材料建模</span><h1>${esc(m?.name||'材料不存在')}</h1>`:`<span class="physical-context">物理建模工作台</span><h1><input data-physical-name aria-label="物理模型名称" value="${esc(s.name)}"></h1>`}<small id="physical-save">已保存在本机（演示）</small></div><span class="physical-state" id="physical-state"></span></div><div class="physical-header-actions">${action('history','变更记录','file')}${!materialId?action('schedule','计算设置','flow'):''}${action('check','检查模型','check')}<button type="button" class="btn primary" data-physical="save">${icon('check')}保存${materialId?'材料':'模型'}</button></div></header><main class="physical-workspace" id="physical-workspace"></main></div>`;
}

export function mountPhysicalEditor(root,s,{materialId,notify,navigate,openDialog,onUpdate}){
  const q=selector=>root.querySelector(selector);let disposePreview=()=>{},disposed=false;
  if(materialId&&s.materials.some(m=>m.id===materialId))s.selectedMaterial=materialId;
  s.materialSection||='properties';
  const current=()=>s.materials.find(m=>m.id===(materialId||s.selectedMaterial));
  function persist(){try{savePhysicalModel(s);q('#physical-save').textContent='已保存在本机（演示）';onUpdate?.(s);}catch{q('#physical-save').textContent='保存失败，请点击保存重试';notify('本机存储空间不足，修改仍保留在当前页面');}}
  function changed(text){touchModel(s,text);persist();render();}
  function tree(){return `<aside class="physical-tree"><div class="physical-panel-title"><strong>${materialId?'材料建模':'模型结构'}</strong><span>${materialId?'材料级':'模型级'}</span></div>${materialId?`<button class="physical-tree-back" data-physical="back-model">${icon('chevron')}返回物理模型</button><div class="physical-tree-label">当前模型中的材料</div>${s.materials.map(m=>`<button class="physical-tree-item ${m.id===materialId?'selected':''}" data-physical="open-material" data-id="${m.id}">${icon('molecule')}<span>${esc(m.name)}<small>${esc(m.region)}</small></span></button>`).join('')}<div class="physical-tree-label">材料配置</div>${[['properties','材料属性'],['structure','分子结构'],['micro','微观模拟']].map(([id,label])=>`<button class="physical-tree-item ${s.materialSection===id?'selected':''}" data-physical="material-section" data-section="${id}">${icon(id==='structure'?'molecule':'flask')}<span>${label}</span></button>`).join('')}`:`<div class="physical-tree-root">${icon('grid')}<strong>${esc(s.geometry.modelName||'物理模型')}</strong></div>${sections.map(([id,label,glyph])=>`<button class="physical-tree-item ${s.section===id?'selected':''}" data-physical="section" data-section="${id}">${icon(glyph)}<span>${label}</span>${id==='materials'?`<small>${s.materials.length}</small>`:''}</button>${id==='materials'?s.materials.map(m=>`<button class="physical-material-tree ${s.selectedMaterial===m.id&&s.section==='materials'?'selected':''}" data-physical="select-material" data-id="${m.id}"><i class="material-dot ${m.region==='颗粒区域'?'filler':''}"></i>${esc(m.name)}</button>`).join(''):''}`).join('')}`}<div class="physical-tree-note">${materialId?'材料配置保存后同步至物理模型。':'在模型中选择材料，再进入材料建模窗口。'}<br>本地原型演示</div></aside>`;}
  function properties(m){return `${input('name','材料名称',m.name,'','text')}${select('region','绑定区域',m.region,[...new Set([m.region,...(s.case==='flow'?['流体域']:['基体区域','颗粒区域']),'未分配'])])}${input('conductivity','热导率',m.conductivity,'W/(m·K)')}${input('density','密度',m.density,'kg/m³')}<p class="physical-note">材料物性由已知数据或后续计算提供，空白值待补充。</p>`;}
  function inspector(){
    const m=current(),p=s.geometry;let body,form='model';
    if(materialId){
      if(!m)return '<div class="physical-empty">该材料已不存在，请返回物理模型选择材料。</div>';
      form='material';
      body=s.materialSection==='structure'?`<h3>分子结构</h3><p class="physical-note">${m.molecule?esc(m.molecule.name)+' · '+esc(moleculeFormula(m.molecule)):'尚未配置结构'}</p>${action('edit-structure',m.molecule?'修改分子结构':'创建分子结构','molecule')}<p class="physical-note">本地结构草稿，尚未关联真实材料结构文件。</p>`:s.materialSection==='micro'?`<h3>微观模拟引用</h3>${input('task','已有微观任务',m.task,'','text')}<p class="physical-note">保留任务引用；实际微观计算服务后续接入。原型不提交真实计算。</p>`:`<h3>材料属性</h3>${properties(m)}`;
    }else if(s.section==='materials'){
      form='material';body=m?`<h3>${esc(m.name)}</h3><div class="physical-region-tag">${esc(m.region)}</div>${action('open-material','进入材料建模','molecule',`data-id="${m.id}"`)}<p class="physical-note">进入此材料的专属窗口，编辑分子结构、材料物性及微观模拟引用。</p>${properties(m)}`:`<h3>材料</h3><p class="physical-note">模型尚未添加材料。</p>${action('add-material','添加材料','plus')}`;
    }else if(s.section==='boundary')body=s.case==='flow'?`<h3>流动边界</h3>${input('inlet','入口速度',p.inlet,'m/s')}${input('outlet','出口表压',p.outlet,'Pa')}`:`<h3>边界条件</h3>${select('direction','计算方向',p.direction||'Z',['X','Y','Z'])}${input('hot','热端温度',p.hot,'°C')}${input('cold','冷端温度',p.cold,'°C')}<p class="physical-note">TIM 示例侧面采用绝热边界。</p>`;
    else if(s.section==='mesh')body=`<h3>网格设置</h3>${input('mesh','目标网格尺寸',p.mesh||.2,'mm')}<p class="physical-note">“显示网格”为几何示意，尚未调用真实网格生成器。</p>`;
    else if(s.section==='physics')body=`<h3>物理场</h3><div class="physical-physics-tag">${esc(s.physics)}</div><p class="physical-note">${s.case==='tim'?'TIM 案例：三维稳态纯导热，示例求解器 Forge FVM V1。':s.case==='flow'?'圆管流动案例，具体算法及流变模型以接口契约为准。':'请先创建几何并选择物理模型。'}</p>${s.case==='generic'?action('create-geometry','创建示例几何','plus'):''}`;
    else body=`<h3>几何设置</h3>${s.case==='generic'?`<p class="physical-note">尚未创建几何。</p>${action('create-geometry','创建示例几何','plus')}`:`<div class="physical-region-tag">${s.case==='flow'?'简单圆管':'基体 / 离散非接触颗粒'}</div>${input('length','长度',p.length,'mm')}${s.case==='flow'?input('diameter','内径',p.diameter,'mm'):input('width','宽度',p.width,'mm')+input('height','厚度',p.height,'mm')+input('gap','最小间隙',p.gap,'mm')+input('target','目标填充率',p.target,'%')}<p class="physical-note">尺寸和填充率为配置示意；真实几何生成与校验待接入。</p>`}`;
    return `<aside class="physical-inspector"><div class="physical-panel-title"><strong>${materialId?'材料配置':'模型配置'}</strong><span>${materialId?'独立材料窗口':sections.find(a=>a[0]===s.section)?.[1]||''}</span></div><form data-physical-form="${form}">${body}${(form==='material'&&m||form==='model'&&s.case!=='generic')?'<button class="btn primary physical-apply" type="submit">保存配置</button>':''}</form></aside>`;
  }
  function scene(){
    const m=current();
    if(materialId)return `<section class="physical-scene"><div class="physical-scene-title"><div><h2>${esc(m?.name||'材料建模')}</h2><span>${esc(m?.region||'')} · 材料级建模</span></div>${m?action('edit-structure',m.molecule?'修改结构':'创建结构','molecule'):''}</div><div class="physical-canvas material-model-canvas" id="physical-preview">${m?.molecule?'':`<div class="physical-empty">${icon('molecule')}<h3>建立材料的分子结构</h3><p>选择示例结构或编辑原子与化学键。</p>${m?action('edit-structure','创建分子结构','plus'):action('back-model','返回物理模型')}</div>`}</div><div class="physical-scene-foot"><span>${m?.molecule?'原型结构示意，非材料真实结构文件。':'结构配置后，分子模型将在此显示。'}</span><span>结构修改只影响当前材料草稿</span></div></section>`;
    return `<div class="physical-center"><section class="physical-scene"><div class="physical-scene-title"><div><h2>物理模型</h2><span>${esc(s.physics)} · ${s.case==='generic'?'等待几何配置':'几何预览'}</span></div><span class="physical-3d-label">3D 视图</span></div><div class="physical-canvas" id="physical-preview">${s.case==='generic'?`<div class="physical-empty">${icon('grid')}<h3>从物理模型开始</h3><p>创建几何后，为模型区域选择材料。</p>${action('create-geometry','创建示例几何','plus')}</div>`:''}</div>${s.case!=='generic'?`<div class="physical-region-picks" aria-label="选择模型材料区域">${s.materials.map(m=>`<button data-physical="select-material" data-id="${m.id}" class="${s.selectedMaterial===m.id&&s.section==='materials'?'selected':''}"><i class="material-dot ${m.region==='颗粒区域'?'filler':''}"></i>${esc(m.region)} · ${esc(m.name)}</button>`).join('')}</div>`:''}</section><section class="physical-materials"><div class="physical-panel-title"><strong>模型材料 <small>${s.materials.length}</small></strong>${action('add-material','添加材料','plus')}</div><div class="physical-material-list">${s.materials.map(m=>`<div class="physical-material-row ${s.selectedMaterial===m.id&&s.section==='materials'?'selected':''}"><button class="physical-material-pick" data-physical="select-material" data-id="${m.id}"><i class="material-dot ${m.region==='颗粒区域'?'filler':''}"></i><span><strong>${esc(m.name)}</strong><small>${esc(m.region)}</small></span><span class="physical-material-property">${m.conductivity!==''?esc(m.conductivity)+' W/(m·K)':'物性待配置'}</span></button><button class="text-btn" data-physical="open-material" data-id="${m.id}">进入材料建模 ${icon('chevron')}</button></div>`).join('')||'<p class="physical-note">添加材料并绑定到几何区域。</p>'}</div></section></div>`;
  }
  function render(){
    if(disposed)return;disposePreview();if(materialId)q('.physical-heading h1').textContent=current()?.name||'材料不存在';q('#physical-state').textContent=s.checkedRevision===s.revision?'已检查':'待检查';
    q('#physical-workspace').innerHTML=tree()+scene()+inspector();const view=q('#physical-preview'),m=current();
    if(materialId&&m?.molecule){const viewer=renderMolecule(view,m.molecule,{height:()=>Math.max(160,view.clientHeight-115),onEdit:editStructure});disposePreview=()=>viewer.destroy();}
    else if(!materialId&&s.case!=='generic')disposePreview=renderPreview(view,s.geometry,{height:()=>Math.max(170,view.clientHeight-85),flow:s.case==='flow',highlight:s.section==='materials'?(m?.region==='颗粒区域'?'materials':'matrix'):s.section});
    else disposePreview=()=>{};
  }
  function editStructure(){const m=current();if(!m)return;openMoleculeEditor(openDialog,m.molecule||createMolecule(),next=>{updateMaterial(s,m.id,{molecule:next,source:'本地结构草稿'});persist();render();notify('材料结构已更新并同步到物理模型');});}
  function addMaterial(){const dialog=openDialog(`<form class="dialog-form" data-add-material><h2>添加模型材料</h2>${input('name','材料名称','','','text')}<p class="physical-note">材料添加后可进入专属窗口，配置结构及物性。</p><div class="dialog-actions"><button class="btn" type="button" data-dialog-close>取消</button><button class="btn primary">添加材料</button></div><p class="editor-form-error" role="alert"></p></form>`);dialog.querySelector('form').onsubmit=e=>{e.preventDefault();const name=dialog.querySelector('[name="name"]').value.trim();if(!name){dialog.querySelector('[role="alert"]').textContent='请填写材料名称';return;}const id='material-'+Date.now();s.materials.push({id,name,region:'未分配',conductivity:'',density:'',molecule:null,task:'',notes:'',source:'本地草稿'});s.selectedMaterial=id;s.section='materials';changed('添加材料：'+name);dialog.close();};}
  function createGeometry(){const dialog=openDialog(`<form class="dialog-form"><h2>创建示例几何</h2><p class="physical-note">选择几何案例作为建模起点，后续可分别配置材料及物理场。</p><label class="physical-field"><span>几何案例</span><select name="case"><option value="tim">颗粒填充基体 · TIM 导热案例</option><option value="flow">简单圆管 · 流动案例</option></select></label><div class="dialog-actions"><button class="btn" type="button" data-dialog-close>取消</button><button class="btn primary">创建几何</button></div></form>`);dialog.querySelector('form').onsubmit=e=>{e.preventDefault();const type=dialog.querySelector('[name="case"]').value,next=createPhysicalModel({workflowId:s.workflowId,id:s.workflowId,name:s.name,type:type==='tim'?'TIM 导热':'流动',nodeCount:4,definitionStatus:'草稿'});s.case=type;s.geometry=macroParams(type);s.materials=next.materials;s.selectedMaterial=next.selectedMaterial;s.physics=next.physics;s.section='geometry';changed('创建示例几何');dialog.close();};}
  function check(){const errors=checkPhysicalModel(s);if(!errors.length){s.checkedRevision=s.revision;persist();render();notify('物理模型的演示配置检查通过');}else openDialog(`<div class="dialog-form"><h2>模型配置待完善</h2><ul class="physical-check-errors">${errors.map(e=>`<li>${esc(e)}</li>`).join('')}</ul><div class="dialog-actions"><button class="btn" data-dialog-close>继续建模</button></div></div>`);}
  function click(e){const b=e.target.closest('[data-physical]');if(!b)return;const a=b.dataset.physical;
    if(a==='back-model')navigate(`/multiscale/workflows/${s.workflowId}/edit`);
    if(a==='section'){s.section=b.dataset.section;persist();render();}
    if(a==='material-section'){s.materialSection=b.dataset.section;persist();render();}
    if(a==='select-material'){s.selectedMaterial=b.dataset.id;s.section='materials';persist();render();}
    if(a==='open-material'){const id=b.dataset.id||s.selectedMaterial;if(id)navigate(materialRoute(s.workflowId,id));}
    if(a==='edit-structure')editStructure();if(a==='add-material')addMaterial();if(a==='create-geometry')createGeometry();if(a==='check')check();
    if(a==='save'){const form=q('[data-physical-form]');if(form)form.requestSubmit();else{persist();notify('模型已保存');}}
    if(a==='history')openDialog(`<div class="dialog-form"><h2>物理模型变更记录</h2>${s.history.slice(0,30).map(h=>`<p class="physical-history-item">${esc(h.text)}<small>${esc(new Date(h.time).toLocaleString('zh-CN'))}</small></p>`).join('')||'<p class="physical-note">暂无变更记录。</p>'}<div class="dialog-actions"><button class="btn" data-dialog-close>关闭</button></div></div>`);
    if(a==='schedule'){const d=openDialog(`<form class="dialog-form"><h2>计算设置</h2><p class="physical-note">当前为配置演示，尚未连接真实调度服务。</p>${input('cores','并行核数',s.scheduler.cores)}${input('retries','失败重试次数',s.scheduler.retries)}<p class="editor-form-error" role="alert"></p><div class="dialog-actions"><button type="button" class="btn" data-dialog-close>取消</button><button class="btn primary">保存设置</button></div></form>`);d.querySelector('form').onsubmit=e=>{e.preventDefault();const data=new FormData(e.target),cores=Number(data.get('cores')),retries=Number(data.get('retries'));if(!Number.isInteger(cores)||cores<1||!Number.isInteger(retries)||retries<0){d.querySelector('[role="alert"]').textContent='核数须为正整数，重试次数须为非负整数';return;}s.scheduler={cores,retries};changed('更新计算设置');d.close();};}
  }
  function submit(e){const form=e.target.closest('[data-physical-form]');if(!form)return;e.preventDefault();const values=Object.fromEntries(new FormData(form));for(const field of form.querySelectorAll('input[type="number"]')){if(field.value!==''&&!Number.isFinite(Number(field.value)))return notify('请填写有效数字');values[field.name]=field.value===''?'':Number(field.value);}
    if(form.dataset.physicalForm==='material'){const m=current();if(!m)return;if('name'in values&&!values.name.trim())return notify('材料名称不能为空');if('name'in values)values.name=values.name.trim();if('conductivity'in values&&values.conductivity!==''&&values.conductivity<=0)return notify('热导率必须大于零');if('density'in values&&values.density!==''&&values.density<=0)return notify('密度必须大于零');if(!Object.entries(values).some(([key,value])=>m[key]!==value)){persist();notify('配置已保存');return;}updateMaterial(s,m.id,values);}else{if(!Object.entries(values).some(([key,value])=>s.geometry[key]!==value)){persist();notify('配置已保存');return;}Object.assign(s.geometry,values);touchModel(s,'保存'+(sections.find(a=>a[0]===s.section)?.[1]||'模型')+'配置');}persist();render();notify('配置已保存');
  }
  function change(e){if(e.target.matches('[data-physical-name]')){if(!e.target.value.trim()){e.target.value=s.name;return notify('模型名称不能为空');}s.name=e.target.value.trim();changed('重命名物理模型');}}
  root.addEventListener('click',click);root.addEventListener('submit',submit);root.addEventListener('change',change);persist();render();
  return ()=>{disposed=true;disposePreview();root.removeEventListener('click',click);root.removeEventListener('submit',submit);root.removeEventListener('change',change);};
}
